export interface InputSanitizer {
  sanitize(input: string): string;
}

export class HtmlEntitySanitizer implements InputSanitizer {
  private readonly SANITIZATION_MAP: Record<string, string> = {
    '<': '&lt;',
    '>': '&gt;',
    '"': '&quot;',
    "'": '&#039;'
  };

  sanitize(input: string): string {
    return input.split('').map(char => 
      this.SANITIZATION_MAP[char] || char
    ).join('');
  }
}
